import js from '@eslint/js';
import tseslint from 'typescript-eslint';
import prettier from 'eslint-config-prettier';
import globals from 'globals';

export default tseslint.config(
  // playwright-report/ and test-results/ are gitignored (Playwright's own HTML report + trace
  // output, regenerated by every `yarn e2e`/`yarn e2e:only` run) but were missing here — lint was
  // only ever green by accident, whenever nobody had run the e2e suite since the last lint pass.
  { ignores: ['out/', '.vite/', 'node_modules/', 'playwright-report/', 'test-results/'] },
  js.configs.recommended,
  ...tseslint.configs.recommended,
  prettier,
  // Main-process test files map raw driver-level results (better-sqlite3 rows, etc.)
  // that come back as `unknown` without an explicit generic; `no-explicit-any` forces
  // every such spot into a cast. Scoped to src/main/**/*.test.ts specifically — this is
  // a main-process-only concern (only main-side tests touch better-sqlite3/Node driver
  // results), so renderer test files keep full type-safety linting.
  { files: ['src/main/**/*.test.ts'], rules: { '@typescript-eslint/no-explicit-any': 'off' } },
  // tests/e2e/harness/fixtures.ts: Playwright's documented zero-dependency fixture idiom is
  // `async ({}, use) => {...}` — the empty object pattern is how a fixture DECLARES it needs no
  // other fixtures (Playwright statically parses the first parameter's destructuring to build the
  // dependency graph), so it's not a stray no-op destructure `no-empty-pattern` is meant to catch.
  { files: ['tests/e2e/harness/fixtures.ts'], rules: { 'no-empty-pattern': 'off' } },
  // scripts/ is developer tooling, not app code: plain ESM JavaScript that runs directly under
  // `electron scripts/…` with no build step, so it needs Node's globals declared (`no-undef` is a
  // no-op in .ts files, where the compiler already owns that question, but it is live here).
  { files: ['scripts/**/*.mjs'], languageOptions: { globals: globals.node } },
);
